package com.example.Help.Service;
import com.example.Help.model.publicacao.*; import com.example.Help.model.social.ParticipanteSocial; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class PublicacaoInteracaoService{
 private final PublicacaoRepository publicacoes; private final CurtidaPublicacaoRepository curtidas; private final ComentarioPublicacaoRepository comentarios; private final SeguidorService seguidores;
 public PublicacaoInteracaoService(PublicacaoRepository p,CurtidaPublicacaoRepository c,ComentarioPublicacaoRepository o,SeguidorService s){publicacoes=p;curtidas=c;comentarios=o;seguidores=s;}
 @Transactional public CurtidaResponseDTO alternarCurtida(UUID id,ParticipanteSocial a){Publicacao p=buscar(id);var e=curtidas.findByPublicacaoIdAndParticipante(id,a.getId(),a.getTipoParticipante());boolean curtiu;if(e.isPresent()){curtidas.delete(e.get());curtiu=false;}else{curtidas.save(new CurtidaPublicacao(p,a));curtiu=true;}return new CurtidaResponseDTO(curtiu,curtidas.countByPublicacaoId(id));}
 @Transactional public ComentarioResponseDTO comentar(UUID id,ParticipanteSocial a,String c){Publicacao p=buscar(id);String texto=c==null?"":c.trim();if(texto.isBlank()||texto.length()>1000)throw new IllegalArgumentException("Comentário inválido.");if(p.getPermissaoComentario()==PermissaoComentario.DESATIVADO)throw new IllegalStateException("Comentários estão desativados nesta publicação.");ParticipanteSocial autor=p.getAutorSocial();boolean proprio=autor.getId().equals(a.getId())&&autor.getTipoParticipante()==a.getTipoParticipante();if(p.getPermissaoComentario()==PermissaoComentario.SEGUIDORES&&!proprio&&!seguidores.estaSeguindo(a,autor.getId(),autor.getTipoParticipante()))throw new IllegalStateException("Apenas seguidores podem comentar nesta publicação.");return ComentarioResponseDTO.from(comentarios.save(new ComentarioPublicacao(p,a,texto)));}
 @Transactional(readOnly=true) public List<ComentarioResponseDTO> listarComentarios(UUID id){buscar(id);return comentarios.findAllByPublicacaoIdOrderByCriadoEmAsc(id).stream().map(ComentarioResponseDTO::from).toList();}
 private Publicacao buscar(UUID id){return publicacoes.findById(id).orElseThrow(()->new IllegalArgumentException("Publicação não encontrada."));}
}
